'use client'

import Link from 'next/link'

import { setupSongGallery } from '@/app/actions/song_modify'
import { useEffect, useState } from 'react'

export default async function Home() {
  const [songArray, setSongs] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    async function fetchSongs() {
      try {
        const dataArray = await setupSongGallery()

        setSongs(dataArray)
      } catch (err) {
        console.error(err)
      } finally {
        setLoading(false)
      }
    }

    fetchSongs()
  }, [])  
  return (
  <>
    <main>

    </main>
  </>
  )
}
